      "notes": [
        "The map should show the current ordinary surrender route where a more specific mechanism replaces the corresponding ECE provisions. ECE can still matter to transitional cases and territories outside those mechanisms.",
        "Additional protocols and all national reservations are not exhaustively encoded.",
        "Russia remains an ECE party in the official 2026 chart. This does not establish that cooperation operates normally or that a court would order surrender.",
        "Ukraine has notified territorial and wartime limits to its ability to implement treaty obligations."
      ],
