      "id": "oas-b47",
      "name": "Inter-American Convention on Extradition",
      "type": "multilateral",
      "status": "in-force",
      "description": "Creates an extradition obligation between ratifying states, subject to conditions and exceptions. It does not automatically replace earlier treaties (Article 33). Only deposited ratifications or accessions are included; other signatures alone do not create coverage.",
      "dateMethod": "Later member effective dates are calculated as 30 days after deposit under Article 31. The initial 28 March 1992 date is the OAS depositary’s published date and is retained as such, although the apparent day-count from Panama’s deposit requires further reconciliation.",
      "signatureDate": "1981-02-25",
      "effectiveDate": "1992-03-28",
      "verifiedAt": "2026-10-22",
      "sources": [
        "source-205",
        "source-206"
      ],
